def scalar(value):
    return value.isoformat() if isinstance(value, (datetime, date)) else value

def read(path):
    wb = openpyxl.load_workbook(path, data_only=True, read_only=True)
    sheet = wb.active
    rows = list(sheet.values)
    headers = rows[0]
    return sheet.title, {i: {h: scalar(v) for h, v in zip(headers, r)} for i, r in enumerate(rows[1:], 2) if any(v is not None for v in r)}

rsheet, notes = read(RELEASE)
