dataset['summary']['primary_2025_mapping_decisions'] = dict(Counter(c['expected']['decision'] for c in cases if c['task']=='release_to_e2e_mapping' and c['benchmark_scope']=='2025_primary'))

# Validate coverage, exact labels, citations, raw snapshots and family partitioning.
assert set(A) == set(notes)
assert len(catalog) == 42 and len(notes) == 65
assert len({c['id'] for c in cases}) == len(cases)
catalog_names = {c['e2e'] for c in catalog}
families = {}
for c in cases:
    families.setdefault(c['group_id'], set()).add(c['split'])
    for e in c['source_evidence']:
        assert isinstance(e['quote'], str) and e['quote'] in notes[e['row']][e['field']]
    if c['task'] == 'release_to_e2e_mapping':
        g = c['expected']
        assert set(g['acceptable_e2e_names'] + g['supporting_e2e_names']) <= catalog_names
        assert (g['decision'] == 'match') == bool(g['acceptable_e2e_names'])
        assert (g['e2e_name'] is not None) == (g['decision'] == 'match')
assert all(len(v) == 1 for v in families.values())
assert [r for r, v in notes.items() if not v['Workday Release'].startswith('Workday 2025')] == dataset['scope']['out_of_year_source_rows']
assert all(c['benchmark_scope'] == ('2025_primary' if notes[c['source_row']]['Workday Release'].startswith('Workday 2025') else 'out_of_year_control') for c in cases)
out = ROOT / 'workday_2025_golden_eval.json'
out.write_text(json.dumps(dataset, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
saved = json.loads(out.read_text(encoding='utf-8'))
assert saved['summary']['case_count'] == len(saved['cases'])
print(json.dumps({'output': str(out), 'bytes': out.stat().st_size, **dataset['summary']}, indent=2))
